from pathlib import Path
import json,base64,unicodedata
p=Path(__file__).parent
old=json.loads((p/'andalucia/js/questions.js').read_text().strip().removeprefix('window.ROSCO_QUESTIONS=').rstrip(';'))
abc=list('ABCDEFGHIJKLMNÑOPQRSTUVWXYZ')
games=[dict(schema='roscolab.v1',id='andalucia',title='Especial Andalucía · 4D',subject='Andalucía',course='Todos los niveles',author='Tecnología Insti',description='El rosco que inició el proyecto: geografía, historia, cultura y patrimonio de Andalucía.',color='#00843d',letters=abc,levels=[dict(name=n,banks=[dict(name='Banco A',questions=old[str(i)]['green']),dict(name='Banco B',questions=old[str(i)]['white'])]) for i,n in enumerate(['Básico','Intermedio','Avanzado','Experto'],1)])]
def game(id,title,subject,course,color,description,banks):
    def bank(name,rows):
        return dict(name=name,questions=[dict(letter=l,mode='contains' if l.casefold()!=unicodedata.normalize('NFD',a[0].casefold())[0] else 'starts',clue=q,answer=a,fact=f,aliases=[],source='') for l,q,a,f in rows])
    games.append(dict(schema='roscolab.v1',id=id,title=title,subject=subject,course=course,author='Tecnología Insti',description=description,color=color,letters=[x[0] for x in banks[0]],levels=[dict(name='Repaso',banks=[bank('Banco '+chr(65+i),r) for i,r in enumerate(banks)])]))
game('electricidad','Electricidad y circuitos','Tecnología y Digitalización','3º ESO','#087c91','Dos bancos de diez letras para repasar conceptos básicos y jugar en duelo.',[[('A','Unidad de medida de la intensidad de corriente.','Amperio','Su símbolo es A.'),('B','Dispositivo formado por una o varias celdas que suministra energía eléctrica.','Batería','Convierte energía química en eléctrica.'),('C','Conjunto de componentes conectados por el que puede circular corriente.','Circuito','Debe existir un camino cerrado para que circule corriente continua.'),('D','Componente que permite el paso de corriente principalmente en un sentido.','Diodo','Un LED es un tipo de diodo.'),('E','Partícula subatómica de carga negativa.','Electrón','Se encuentra en los átomos.'),('F','Elemento de protección que se funde cuando la corriente es excesiva.','Fusible','Interrumpe el circuito.'),('G','Dispositivo que transforma otra forma de energía en eléctrica.','Generador','Una dinamo es un ejemplo.'),('H','Unidad de inductancia del Sistema Internacional.','Henrio','Su símbolo es H.'),('I','Dispositivo que permite abrir o cerrar un circuito.','Interruptor','Controla el paso de corriente.'),('J','Unidad de energía del Sistema Internacional, también llamada julio.','Julio','Su símbolo es J.')],[('A','Instrumento para medir la intensidad de corriente.','Amperímetro','Se conecta en serie para medir corriente.'),('B','Componente que consiste en un hilo conductor enrollado.','Bobina','Puede producir un campo magnético.'),('C','Material que facilita el paso de corriente.','Conductor','El cobre es un ejemplo.'),('D','Máquina que convierte energía mecánica en eléctrica mediante inducción.','Dinamo','Produce corriente continua.'),('E','Magnitud que representa la capacidad de realizar trabajo.','Energía','Se mide en julios.'),('F','Magnitud que indica cuántas veces se repite un fenómeno por segundo.','Frecuencia','Se mide en hercios.'),('G','Nombre de la conexión eléctrica a tierra en muchos esquemas en inglés.','GND','Es una abreviatura de ground.'),('H','Unidad de frecuencia del Sistema Internacional.','Hercio','Su símbolo es Hz.'),('I','Magnitud que mide la carga que atraviesa una sección por unidad de tiempo.','Intensidad','Se mide en amperios.'),('J','Apellido del científico que da nombre al efecto de calentamiento de un conductor por la corriente.','Joule','El efecto Joule transforma energía eléctrica en térmica.')]])
game('matematicas','Reto matemático','Matemáticas','2º ESO','#2563eb','Minirosco de geometría, números y álgebra.',[[('A','Medida de una superficie.','Área','Se expresa en unidades cuadradas.'),('B','Lado de referencia de un triángulo para calcular su área.','Base','Área = base × altura / 2.'),('C','Figura plana limitada por una circunferencia.','Círculo','Incluye su interior.'),('D','Segmento que une dos puntos de una circunferencia pasando por el centro.','Diámetro','Es el doble del radio.'),('E','Igualdad matemática que contiene una incógnita.','Ecuación','Resolverla consiste en hallar los valores que cumplen la igualdad.'),('F','Expresión que representa el cociente entre dos números enteros con denominador no nulo.','Fracción','Tiene numerador y denominador.'),('G','Unidad habitual de medida de ángulos.','Grado','Una vuelta completa son 360 grados.'),('H','Lado más largo de un triángulo rectángulo.','Hipotenusa','Se opone al ángulo recto.'),('I','Valor desconocido que buscamos en una ecuación.','Incógnita','Suele representarse con x.'),('J','Agrupación de elementos que comparten una propiedad o se consideran como una colección.','Conjunto','Se representa a menudo mediante llaves.')]])
game('lengua','Palabras y gramática','Lengua y Literatura','1º ESO','#bd3650','Diez conceptos para repasar clases de palabras y comunicación.',[[('A','Palabra que expresa una cualidad o característica de un sustantivo.','Adjetivo','Concuerda habitualmente en género y número.'),('B','Conjunto de libros y otros recursos disponible para consulta.','Biblioteca','Puede ser física o digital.'),('C','Palabra invariable que enlaza palabras u oraciones.','Conjunción','Por ejemplo: y, pero, o.'),('D','Palabra que acompaña al sustantivo para precisar su referencia.','Determinante','Los artículos son determinantes.'),('E','Persona que transmite un mensaje.','Emisor','Forma parte del proceso comunicativo.'),('F','Grupo de palabras con sentido que no tiene por qué constituir una oración.','Frase','Puede carecer de verbo conjugado.'),('G','Categoría gramatical que distingue, por ejemplo, masculino y femenino.','Género','Afecta a la concordancia.'),('H','Palabra escrita igual que otra con distinto significado; puede tener origen diferente.','Homógrafa','Banco tiene distintas acepciones.'),('I','Forma no personal del verbo terminada en -ar, -er o -ir.','Infinitivo','Cantar, comer, vivir.'),('J','Palabra que nombra una variedad lingüística propia de una profesión o grupo.','Jerga','Puede contener vocabulario especializado.')]])
# make original script safe to embed; actual text still parsed as JSON
(p/'src/catalog.json').write_text(json.dumps({'games':games},ensure_ascii=False,indent=2))
logo='data:image/webp;base64,'+base64.b64encode((p/'assets/logo-tecnologiainsti.webp').read_bytes()).decode()
html=(p/'src/shell.html').read_text().replace('__CSS__',(p/'src/style.css').read_text()).replace('__LOGO__',logo).replace('__DATA__',json.dumps({'games':games},ensure_ascii=False).replace('<','\\u003c')).replace('__JS__',(p/'src/app.js').read_text())
(p/'index.html').write_text(html)
